"""catalog/visuals.json (generated by library/tools/export_visuals.luau) has the shape skills rely on.

Freshness is checked in CI by `lune run tools/export_visuals --check`; these tests need no Luau tools.
"""
import json
import re
import unittest

from _util import ROOT

KINDS = {"vfx", "ui", "object", "camera", "pet", "rarity", "feedback", "audio", "theme", "component"}
FIELDS = ("id", "name", "category", "description", "params", "quality", "usage")
LEVELS = ("Low", "Medium", "High", "Ultra")


class VisualsCatalogTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.data = json.loads((ROOT / "catalog/visuals.json").read_text(encoding="utf-8"))
        cls.kinds = cls.data["kinds"]

    def test_kinds_and_counts(self):
        self.assertTrue(KINDS <= set(self.kinds), f"missing kinds: {KINDS - set(self.kinds)}")
        self.assertEqual(self.data["counts"], {k: len(v) for k, v in self.kinds.items()})
        self.assertEqual(self.data["total"], sum(len(v) for v in self.kinds.values()))
        for kind in KINDS:
            self.assertGreater(len(self.kinds[kind]), 0, kind)

    def test_entries(self):
        for kind, items in self.kinds.items():
            ids = [i["id"] for i in items]
            self.assertEqual(len(ids), len(set(ids)), f"duplicate ids in {kind}")
            for item in items:
                with self.subTest(kind=kind, id=item.get("id")):
                    for field in FIELDS:
                        self.assertIn(field, item)
                    self.assertIsInstance(item["params"], dict)
                    self.assertGreaterEqual(len(item["description"]), 12)
                    self.assertIn(item["quality"].get("cost"), ("low", "medium", "high"))
                    self.assertIn(item["quality"].get("min"), LEVELS)
                    # Case-insensitive: camera move presets are functions (Zoom -> Camera.zoom).
                    self.assertIn(item["id"].lower(), item["usage"].lower(), "the usage line must mention the id")
                    for name, param in item["params"].items():
                        self.assertIn(param.get("type"), ("number", "color", "boolean", "string", "enum"), name)

    def test_sorted_and_deterministic(self):
        for kind, items in self.kinds.items():
            if kind == "rarity":  # kept in rank order
                ranks = [i["rank"] for i in items]
                self.assertEqual(ranks, sorted(ranks))
                continue
            ids = [i["id"] for i in items]
            self.assertEqual(ids, sorted(ids), f"{kind} is not sorted by id")
        text = (ROOT / "catalog/visuals.json").read_text(encoding="utf-8")
        self.assertTrue(text.endswith("}\n"))
        self.assertNotIn("\r", text)

    def test_quality_profiles(self):
        self.assertEqual(sorted(self.data["quality"]), sorted(LEVELS))
        budgets = [self.data["quality"][level]["maxParticles"] for level in LEVELS]
        self.assertEqual(budgets, sorted(budgets))

    def test_cross_references(self):
        """Rarity profiles and feedback recipes only name presets and cues that exist."""
        vfx = {i["id"] for i in self.kinds["vfx"]}
        cues = {i["id"] for i in self.kinds["audio"]}
        by_kind = {
            "vfx": vfx, "ui": {i["id"] for i in self.kinds["ui"]}, "object": {i["id"] for i in self.kinds["object"]},
            "camera": {i["id"] for i in self.kinds["camera"]}, "pet": {i["id"] for i in self.kinds["pet"]}, "sound": cues,
        }
        for rarity in self.kinds["rarity"]:
            self.assertTrue(set(rarity["vfx"]) <= vfx, rarity["id"])
            self.assertTrue(set(rarity["sounds"]) <= cues, rarity["id"])
        for event in self.kinds["feedback"]:
            for step in event["steps"]:
                kind, _, ref = step.partition(":")
                if ref and kind in by_kind and not ref.startswith("$") and re.match(r"^[A-Za-z.]+$", ref):
                    if kind == "ui" and ref[0].islower():
                        continue  # a ui action name (countTo, shine, flash), not a preset
                    with self.subTest(event=event["id"], step=step):
                        self.assertIn(ref, by_kind[kind])

    def test_generated_preset_tables_are_current(self):
        """Skill references and docs/references/visuals-presets.md match the catalog."""
        import automation.build_visuals_refs as refs
        stale = [str(p.relative_to(ROOT)) for p, text in refs.targets(self.data).items()
                 if not p.exists() or p.read_text(encoding="utf-8") != text]
        self.assertEqual(stale, [], "run python3 scripts/automation/build_visuals_refs.py")

    def test_skills_point_to_the_catalog(self):
        entry = (ROOT / "skills/visuals/uvk-visuals-kit/SKILL.md").read_text(encoding="utf-8")
        self.assertIn("catalog/visuals.json", entry)
        for skill in sorted((ROOT / "skills/visuals").glob("*/SKILL.md")):
            with self.subTest(skill=skill.parent.name):
                text = skill.read_text(encoding="utf-8")
                self.assertTrue("catalog/visuals.json" in text or "uvk-visuals-kit" in text)
                self.assertIn("NEEDS MANUAL REVIEW", text, "visual skills must say what is unverified")

    def test_no_third_party_names(self):
        text = (ROOT / "catalog/visuals.json").read_text(encoding="utf-8").lower()
        for banned in ("blox fruits", "pet simulator", "adopt me", "bee swarm", "brainrot"):
            self.assertNotIn(banned, text)


if __name__ == "__main__":
    unittest.main()
